  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C51"],
      "claim": "Molecule 1 in the post-prandial state had an absolute bioavailability of 36.40% in patients (oral capsule, 6.6 mg/kg vs IV), directly supporting F >= 20% under fed conditions."
    },
    {
      "card_ids": ["C14"],
      "claim": "Molecule 10 in the postprandial state had an absolute bioavailability of 90.8% in healthy Japanese subjects (5 mg oral vs IV), directly supporting high bioavailability under fed conditions."
    },
    {
      "card_ids": ["C32"],
      "claim": "Molecule 9 is mixed: a representative absolute bioavailability value was 15.5% in healthy subjects, while other absolute records report higher values; this introduces uncertainty but does not outweigh the direct fed-state positive evidence."
    }
  ],
  "confidence": "moderate",
  "contradictory_card_ids": ["C32"],
  "decision_summary": "Direct fed-state absolute bioavailability values for Molecules 1 and 10 exceed the 20% threshold, and most other transferred molecules also support high; Molecule 9 is mixed, so high is predicted with moderate confidence.",
  "evidence_gaps": [
    "Molecule 9 has mixed absolute bioavailability values and no fed-state record, so its direction is uncertain.",
    "Molecules 6 and 7 provide only qualitative 'poor' bioavailability without threshold-relevant numeric values, so they are uninformative."
  ],
  "new_evidence_assessment": [],
  "prediction_basis_card_ids": ["C51", "C14"],
  "revision_action": "initial",
